ALTER TABLE public.memorials ADD COLUMN IF NOT EXISTS family_consent_confirmed boolean NOT NULL DEFAULT false;
ALTER TABLE public.family_members ADD COLUMN IF NOT EXISTS consent_confirmed boolean NOT NULL DEFAULT false;
ALTER TABLE public.family_members ADD COLUMN IF NOT EXISTS is_minor boolean NOT NULL DEFAULT false;
ALTER TABLE public.family_members ADD COLUMN IF NOT EXISTS privacy_mode text NOT NULL DEFAULT 'abbreviated';
ALTER TABLE public.family_members ADD CONSTRAINT family_privacy_mode_values CHECK (privacy_mode IN ('abbreviated','initials','family'));
CREATE OR REPLACE FUNCTION public.validate_family_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.is_minor AND NEW.privacy_mode='abbreviated' THEN NEW.privacy_mode:='initials'; END IF; IF NEW.privacy_mode <> 'family' AND NOT NEW.consent_confirmed THEN RAISE EXCEPTION 'Confirm consent from the living relative or the minor''s parent or guardian before publication'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_family_privacy BEFORE INSERT OR UPDATE OF name,photo_url,is_minor,privacy_mode,consent_confirmed ON public.family_members FOR EACH ROW EXECUTE FUNCTION public.validate_family_privacy();
DROP POLICY IF EXISTS "view family members" ON public.family_members;
DROP POLICY IF EXISTS "admins manage family" ON public.family_members;
CREATE POLICY "authorized family management" ON public.family_members FOR ALL TO authenticated USING (public.is_memorial_admin(memorial_id,auth.uid()) OR public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.is_memorial_admin(memorial_id,auth.uid()) OR public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.public_family_members(_memorial_id uuid) RETURNS TABLE(id uuid,name text,relationship text,photo_url text,display_order integer,is_minor boolean,privacy_mode text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT f.id, CASE WHEN f.is_minor OR f.privacy_mode='initials' THEN (SELECT string_agg(upper(left(word,1))||'.','' ORDER BY ord) FROM regexp_split_to_table(trim(f.name),'\s+') WITH ORDINALITY t(word,ord)) ELSE split_part(trim(f.name),' ',1) || coalesce((SELECT ' '||string_agg(upper(left(word,1))||'.','' ORDER BY ord) FROM regexp_split_to_table(trim(f.name),'\s+') WITH ORDINALITY t(word,ord) WHERE ord>1),'') END,f.relationship,CASE WHEN f.is_minor OR f.privacy_mode='initials' THEN NULL ELSE f.photo_url END,f.display_order,f.is_minor,f.privacy_mode FROM public.family_members f JOIN public.memorials m ON m.id=f.memorial_id WHERE m.id=_memorial_id AND ((m.is_public AND m.family_consent_confirmed AND f.consent_confirmed AND f.privacy_mode<>'family') OR public.is_memorial_admin(m.id,auth.uid()) OR public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'admin')); $$;
REVOKE ALL ON FUNCTION public.public_family_members(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_family_members(uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.mask_donor_phone(phone text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN phone IS NULL THEN NULL WHEN phone LIKE '%X%' THEN phone WHEN length(digits)<6 THEN 'Hidden' ELSE left(digits,2)||'XX XXX '||right(digits,3) END FROM (SELECT CASE WHEN regexp_replace(phone,'\D','','g') LIKE '254%' THEN '0'||substr(regexp_replace(phone,'\D','','g'),4) ELSE regexp_replace(phone,'\D','','g') END AS digits) s; $$;
REVOKE SELECT ON public.donations FROM anon,authenticated;
GRANT SELECT(id,fundraiser_id,user_id,donor_name,amount,is_anonymous,message,created_at,status,payment_method) ON public.donations TO authenticated;
CREATE VIEW public.masked_donations WITH (security_barrier=true) AS SELECT d.id,d.fundraiser_id,d.user_id,CASE WHEN d.is_anonymous THEN 'Anonymous' ELSE d.donor_name END donor_name,d.amount,d.is_anonymous,d.message,d.created_at,NULL::text stripe_session_id,NULL::text donor_email,d.status,CASE WHEN d.is_anonymous THEN NULL ELSE public.mask_donor_phone(d.donor_phone) END donor_phone,d.payment_method FROM public.donations d WHERE d.status='paid' OR d.user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.fundraisers f WHERE f.id=d.fundraiser_id AND (public.is_memorial_admin(f.memorial_id,auth.uid()) OR public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'admin')));
GRANT SELECT ON public.masked_donations TO anon,authenticated,service_role;
CREATE TABLE public.privacy_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),memorial_id uuid REFERENCES public.memorials(id) ON DELETE SET NULL,requester_name text NOT NULL,email text NOT NULL,request_type text NOT NULL DEFAULT 'removal',details text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,legal_hold boolean NOT NULL DEFAULT false);
GRANT INSERT ON public.privacy_requests TO anon,authenticated;
GRANT SELECT,UPDATE ON public.privacy_requests TO authenticated;
GRANT ALL ON public.privacy_requests TO service_role;
ALTER TABLE public.privacy_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "submit privacy request" ON public.privacy_requests FOR INSERT TO anon,authenticated WITH CHECK (status='open' AND closed_at IS NULL AND legal_hold=false AND length(requester_name) BETWEEN 2 AND 100 AND length(email) BETWEEN 3 AND 254 AND email LIKE '%@%' AND length(details) BETWEEN 10 AND 3000 AND request_type IN ('removal','access','correction','objection','restriction','portability','consent'));
CREATE POLICY "privacy staff reads requests" ON public.privacy_requests FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'admin'));
CREATE POLICY "privacy staff updates requests" ON public.privacy_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'admin')) WITH CHECK(status IN ('open','in_review','closed'));
ALTER TABLE public.donations ADD COLUMN IF NOT EXISTS legal_hold boolean NOT NULL DEFAULT false;
ALTER TABLE public.donation_receipts ADD COLUMN IF NOT EXISTS legal_hold boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.purge_privacy_retention() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.site_visits WHERE created_at < now()-interval '90 days'; DELETE FROM public.privacy_requests WHERE status='closed' AND closed_at < now()-interval '12 months' AND NOT legal_hold; DELETE FROM public.donation_receipts r WHERE r.created_at < now()-interval '7 years' AND NOT r.legal_hold AND NOT EXISTS(SELECT 1 FROM public.donations d WHERE d.id=r.donation_id AND d.legal_hold); DELETE FROM public.donations d WHERE d.created_at < now()-interval '7 years' AND NOT d.legal_hold AND NOT EXISTS(SELECT 1 FROM public.donation_receipts r WHERE r.donation_id=d.id); END; $$;
REVOKE ALL ON FUNCTION public.purge_privacy_retention() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.purge_privacy_retention() TO service_role;
SELECT cron.schedule('makiwa-privacy-retention','17 2 * * *','SELECT public.purge_privacy_retention()');